:root {
  --bg: #1a1a2e;
  --card: #16213e;
  --primary: #e94560;
  --text: #eaeaea;
  --accent: #0f3460;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  background: var(--bg);
  font-family: 'Courier New', monospace;
  font-size: 18px;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  color: var(--text);
}

.card {
  background: var(--card);
  border: 4px solid var(--primary);
  border-radius: 0;
  padding: 32px 24px;
  width: 100%;
  max-width: 400px;
  text-align: center;
  box-shadow: 8px 8px 0 rgba(0, 0, 0, 0.4);
}

h1 {
  font-size: 1.5rem;
  letter-spacing: 2px;
  margin-bottom: 24px;
  color: var(--primary);
  text-transform: uppercase;
}

.mode-toggle {
  display: flex;
  gap: 8px;
  justify-content: center;
  margin-bottom: 24px;
}

.mode-btn {
  background: var(--accent);
  color: var(--text);
  border: 3px solid transparent;
  padding: 10px 16px;
  font-family: inherit;
  font-size: 1rem;
  cursor: pointer;
  transition: all 0.15s;
}

.mode-btn:hover {
  border-color: var(--primary);
}

.mode-btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.mode-btn.active {
  background: var(--primary);
  color: #fff;
  border-color: #fff;
}

.mode-btn:active {
  transform: translate(2px, 2px);
}

.timer {
  font-size: 4rem;
  font-weight: bold;
  letter-spacing: 4px;
  margin: 16px 0 32px;
  color: var(--text);
  text-shadow: 3px 3px 0 var(--primary);
  font-variant-numeric: tabular-nums;
}

.controls {
  display: flex;
  gap: 12px;
  justify-content: center;
}

.btn {
  background: var(--accent);
  color: var(--text);
  border: 3px solid var(--text);
  padding: 12px 24px;
  font-family: inherit;
  font-size: 1.1rem;
  cursor: pointer;
  transition: all 0.15s;
  min-width: 100px;
}

.btn:hover {
  background: var(--primary);
  border-color: #fff;
}

.btn:focus-visible {
  outline: 3px solid var(--primary);
  outline-offset: 2px;
}

.btn:active {
  transform: translate(2px, 2px);
}

.btn.primary {
  background: var(--primary);
  border-color: #fff;
}

.btn.primary:hover {
  background: #ff5c77;
}

@media (max-width: 400px) {
  .timer {
    font-size: 3rem;
  }
  .btn {
    padding: 10px 16px;
    min-width: 80px;
  }
  .card {
    padding: 24px 16px;
  }
}

const WORK_TIME = 25 * 60;
const BREAK_TIME = 5 * 60;

let timeLeft = WORK_TIME;
let timerId = null;
let isRunning = false;
let isWorkMode = true;

const timerDisplay = document.getElementById('timer-display');
const startPauseBtn = document.getElementById('start-pause');
const resetBtn = document.getElementById('reset');
const modeWorkBtn = document.getElementById('mode-work');
const modeBreakBtn = document.getElementById('mode-break');

function formatTime(seconds) {
  const m = Math.floor(seconds / 60).toString().padStart(2, '0');
  const s = (seconds % 60).toString().padStart(2, '0');
  return `${m}:${s}`;
}

function updateDisplay() {
  timerDisplay.textContent = formatTime(timeLeft);
}

function setMode(work) {
  if (isRunning) return;
  isWorkMode = work;
  timeLeft = work ? WORK_TIME : BREAK_TIME;
  updateDisplay();
  modeWorkBtn.classList.toggle('active', work);
  modeBreakBtn.classList.toggle('active', !work);
  modeWorkBtn.setAttribute('aria-pressed', work.toString());
  modeBreakBtn.setAttribute('aria-pressed', (!work).toString());
}

function tick() {
  if (timeLeft > 0) {
    timeLeft--;
    updateDisplay();
  } else {
    pauseTimer();
    // Auto-switch mode on completion
    setMode(!isWorkMode);
  }
}

function startTimer() {
  if (isRunning) return;
  isRunning = true;
  startPauseBtn.textContent = 'Pause';
  timerId = setInterval(tick, 1000);
}

function pauseTimer() {
  isRunning = false;
  startPauseBtn.textContent = 'Start';
  clearInterval(timerId);
  timerId = null;
}

function resetTimer() {
  pauseTimer();
  timeLeft = isWorkMode ? WORK_TIME : BREAK_TIME;
  updateDisplay();
}

startPauseBtn.addEventListener('click', () => {
  if (isRunning) {
    pauseTimer();
  } else {
    startTimer();
  }
});

resetBtn.addEventListener('click', resetTimer);

modeWorkBtn.addEventListener('click', () => {
  if (!isRunning) setMode(true);
});

modeBreakBtn.addEventListener('click', () => {
  if (!isRunning) setMode(false);
});

// Initialize
updateDisplay();
